#!/usr/bin/env python3
from pathlib import Path
import sys

ROOT = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path.cwd()

API_ROUTE = "import { createHash } from \"node:crypto\";\n\nimport { NextRequest, NextResponse } from \"next/server\";\n\nimport { getStaffSession } from \"@/lib/auth/require-staff\";\nimport { createAdminClient } from \"@/lib/supabase/admin\";\n\nexport const runtime = \"nodejs\";\nexport const dynamic = \"force-dynamic\";\n\nconst BUCKET = \"rich-text-images\";\nconst MAX_BYTES = 8 * 1024 * 1024;\n\nconst ALLOWED_TYPES = new Map<string, string>([\n  [\"image/png\", \"png\"],\n  [\"image/jpeg\", \"jpg\"],\n  [\"image/webp\", \"webp\"],\n  [\"image/gif\", \"gif\"],\n]);\n\nasync function requireImageStaff() {\n  const staff = await getStaffSession();\n\n  if (\n    !staff ||\n    ![\"owner\", \"admin\", \"master\"].includes(\n      staff.role,\n    )\n  ) {\n    return null;\n  }\n\n  return staff;\n}\n\nfunction bad(\n  error: string,\n  status = 400,\n) {\n  return NextResponse.json(\n    { error },\n    { status },\n  );\n}\n\nexport async function GET(\n  request: NextRequest,\n) {\n  const staff =\n    await requireImageStaff();\n\n  if (!staff) {\n    return bad(\n      \"Not authorised.\",\n      403,\n    );\n  }\n\n  if (\n    request.nextUrl.searchParams.get(\n      \"probe\",\n    ) === \"1\"\n  ) {\n    return NextResponse.json({\n      ok: true,\n      canUpload: true,\n    });\n  }\n\n  const q =\n    String(\n      request.nextUrl.searchParams.get(\n        \"q\",\n      ) ?? \"\",\n    )\n      .trim()\n      .slice(0, 120);\n\n  const limit = Math.min(\n    200,\n    Math.max(\n      1,\n      Number(\n        request.nextUrl.searchParams.get(\n          \"limit\",\n        ) ?? 100,\n      ) || 100,\n    ),\n  );\n\n  const admin =\n    createAdminClient();\n\n  let query =\n    admin\n      .from(\"rich_text_images\")\n      .select(\n        \"id, public_url, original_name, mime_type, size_bytes, sha256, created_at\",\n      )\n      .order(\n        \"created_at\",\n        {\n          ascending: false,\n        },\n      )\n      .limit(limit);\n\n  if (q) {\n    query =\n      query.ilike(\n        \"original_name\",\n        `%${q.replaceAll(\"%\", \"\\\\%\").replaceAll(\"_\", \"\\\\_\")}%`,\n      );\n  }\n\n  const {\n    data,\n    error,\n  } = await query;\n\n  if (error) {\n    return bad(\n      error.message,\n      500,\n    );\n  }\n\n  return NextResponse.json({\n    ok: true,\n    images: data ?? [],\n  });\n}\n\nexport async function POST(\n  request: NextRequest,\n) {\n  const staff =\n    await requireImageStaff();\n\n  if (!staff) {\n    return bad(\n      \"Not authorised.\",\n      403,\n    );\n  }\n\n  const formData =\n    await request.formData();\n\n  const file =\n    formData.get(\"file\");\n\n  if (!(file instanceof File)) {\n    return bad(\n      \"Choose an image.\",\n    );\n  }\n\n  if (\n    file.size <= 0 ||\n    file.size > MAX_BYTES\n  ) {\n    return bad(\n      \"Images cannot exceed 8 MB.\",\n    );\n  }\n\n  const extension =\n    ALLOWED_TYPES.get(\n      file.type,\n    );\n\n  if (!extension) {\n    return bad(\n      \"Images must be PNG, JPEG, WEBP or GIF.\",\n    );\n  }\n\n  const bytes =\n    Buffer.from(\n      await file.arrayBuffer(),\n    );\n\n  const sha256 =\n    createHash(\"sha256\")\n      .update(bytes)\n      .digest(\"hex\");\n\n  const admin =\n    createAdminClient();\n\n  const {\n    data: existing,\n    error: existingError,\n  } = await admin\n    .from(\"rich_text_images\")\n    .select(\n      \"id, public_url, original_name, mime_type, size_bytes, sha256, created_at\",\n    )\n    .eq(\n      \"sha256\",\n      sha256,\n    )\n    .maybeSingle();\n\n  if (existingError) {\n    return bad(\n      existingError.message,\n      500,\n    );\n  }\n\n  if (existing) {\n    return NextResponse.json({\n      ok: true,\n      reused: true,\n      image: existing,\n    });\n  }\n\n  const storagePath =\n    `${sha256}.${extension}`;\n\n  const {\n    error: uploadError,\n  } = await admin.storage\n    .from(BUCKET)\n    .upload(\n      storagePath,\n      bytes,\n      {\n        contentType:\n          file.type,\n        upsert: false,\n        cacheControl: \"31536000\",\n      },\n    );\n\n  if (\n    uploadError &&\n    !uploadError.message\n      .toLowerCase()\n      .includes(\"already exists\")\n  ) {\n    return bad(\n      uploadError.message,\n      500,\n    );\n  }\n\n  const publicUrl =\n    admin.storage\n      .from(BUCKET)\n      .getPublicUrl(\n        storagePath,\n      )\n      .data.publicUrl;\n\n  const {\n    data: inserted,\n    error: insertError,\n  } = await admin\n    .from(\"rich_text_images\")\n    .insert({\n      sha256,\n      storage_path:\n        storagePath,\n      public_url:\n        publicUrl,\n      original_name:\n        file.name ||\n        `clipboard.${extension}`,\n      mime_type:\n        file.type,\n      size_bytes:\n        file.size,\n      uploaded_by_user_id:\n        staff.userId,\n    })\n    .select(\n      \"id, public_url, original_name, mime_type, size_bytes, sha256, created_at\",\n    )\n    .single();\n\n  if (insertError) {\n    if (\n      insertError.code ===\n      \"23505\"\n    ) {\n      const {\n        data: raced,\n      } = await admin\n        .from(\"rich_text_images\")\n        .select(\n          \"id, public_url, original_name, mime_type, size_bytes, sha256, created_at\",\n        )\n        .eq(\n          \"sha256\",\n          sha256,\n        )\n        .maybeSingle();\n\n      if (raced) {\n        return NextResponse.json({\n          ok: true,\n          reused: true,\n          image: raced,\n        });\n      }\n    }\n\n    return bad(\n      insertError.message,\n      500,\n    );\n  }\n\n  return NextResponse.json({\n    ok: true,\n    reused: false,\n    image: inserted,\n  });\n}\n"
SQL = "begin;\n\ninsert into storage.buckets (\n  id,\n  name,\n  public\n)\nvalues (\n  'rich-text-images',\n  'rich-text-images',\n  true\n)\non conflict (id)\ndo update\nset public = true;\n\ncreate table if not exists public.rich_text_images (\n  id uuid primary key default gen_random_uuid(),\n  sha256 text not null unique,\n  storage_path text not null unique,\n  public_url text not null,\n  original_name text not null,\n  mime_type text not null,\n  size_bytes bigint not null check (size_bytes >= 0),\n  uploaded_by_user_id uuid null references auth.users(id) on delete set null,\n  created_at timestamptz not null default now()\n);\n\ncreate index if not exists rich_text_images_created_at_idx\non public.rich_text_images (created_at desc);\n\nalter table public.rich_text_images enable row level security;\n\ncommit;\n"

api_path = ROOT / "app/api/editor/rich-text-images/route.ts"
api_path.parent.mkdir(parents=True, exist_ok=True)
api_path.write_text(API_ROUTE, encoding='utf-8')
print(f"WRITE {api_path}")

def apply(path_str, old, new, label):
    path = ROOT / path_str
    if not path.exists():
        raise SystemExit(f'Missing file: {path}')
    text = path.read_text(encoding='utf-8')
    if new in text and old not in text:
        print(f'SKIP  {label} (already patched)')
        return
    if old not in text:
        raise SystemExit(f'Could not patch {label}: expected block not found in {path_str}.')
    path.write_text(text.replace(old, new, 1), encoding='utf-8')
    print(f'PATCH {label}')

apply("components/editor/rich-text-editor.tsx", "  const textLength = visibleLength(html);\n", "\ntype RichTextLibraryImage = {\n  id: string;\n  public_url: string;\n  original_name: string;\n  mime_type: string;\n  size_bytes: number;\n  sha256: string;\n  created_at: string;\n};\n\nconst imageInsertRangeRef =\n  useRef<Range | null>(null);\n\nconst [\n  canUseImageLibrary,\n  setCanUseImageLibrary,\n] = useState(false);\n\nconst [\n  imageLibraryOpen,\n  setImageLibraryOpen,\n] = useState(false);\n\nconst [\n  imageLibraryImages,\n  setImageLibraryImages,\n] = useState<\n  RichTextLibraryImage[]\n>([]);\n\nconst [\n  imageLibraryLoading,\n  setImageLibraryLoading,\n] = useState(false);\n\nconst [\n  imageLibrarySearch,\n  setImageLibrarySearch,\n] = useState(\"\");\n\nconst [\n  imageUploadBusy,\n  setImageUploadBusy,\n] = useState(false);\n\nconst [\n  imageLibraryError,\n  setImageLibraryError,\n] = useState<string | null>(null);\n\nuseEffect(() => {\n  let active = true;\n\n  void fetch(\n    \"/api/editor/rich-text-images?probe=1\",\n    {\n      cache: \"no-store\",\n    },\n  )\n    .then((response) => {\n      if (\n        active &&\n        response.ok\n      ) {\n        setCanUseImageLibrary(true);\n      }\n    })\n    .catch(() => {\n      // Ordinary users and unavailable endpoints simply keep URL-only images.\n    });\n\n  return () => {\n    active = false;\n  };\n}, []);\n\nfunction rememberImageInsertRange() {\n  const editor =\n    editorRef.current;\n\n  const selection =\n    window.getSelection();\n\n  if (\n    !editor ||\n    !selection ||\n    selection.rangeCount === 0\n  ) {\n    imageInsertRangeRef.current =\n      null;\n    return;\n  }\n\n  const range =\n    selection.getRangeAt(0);\n\n  if (\n    !editor.contains(\n      range.commonAncestorContainer,\n    )\n  ) {\n    imageInsertRangeRef.current =\n      null;\n    return;\n  }\n\n  imageInsertRangeRef.current =\n    range.cloneRange();\n}\n\nfunction insertLibraryImage(\n  url: string,\n  rangeOverride?: Range | null,\n) {\n  const editor =\n    editorRef.current;\n\n  if (\n    !editor ||\n    !url\n  ) {\n    return;\n  }\n\n  editor.focus();\n\n  const selection =\n    window.getSelection();\n\n  if (!selection) {\n    return;\n  }\n\n  let range =\n    rangeOverride ??\n    imageInsertRangeRef.current;\n\n  if (\n    !range ||\n    !editor.contains(\n      range.commonAncestorContainer,\n    )\n  ) {\n    range =\n      document.createRange();\n\n    range.selectNodeContents(\n      editor,\n    );\n\n    range.collapse(false);\n  }\n\n  const image =\n    document.createElement(\n      \"img\",\n    );\n\n  image.src = url;\n  image.alt = \"\";\n\n  range.deleteContents();\n  range.insertNode(image);\n\n  const trailingBreak =\n    document.createElement(\n      \"br\",\n    );\n\n  image.after(\n    trailingBreak,\n  );\n\n  const caret =\n    document.createRange();\n\n  caret.setStartAfter(\n    trailingBreak,\n  );\n\n  caret.collapse(true);\n\n  selection.removeAllRanges();\n  selection.addRange(caret);\n\n  imageInsertRangeRef.current =\n    caret.cloneRange();\n\n  syncFromEditor();\n}\n\nasync function uploadRichTextImage(\n  file: File,\n  range?: Range | null,\n) {\n  if (\n    !canUseImageLibrary ||\n    imageUploadBusy\n  ) {\n    return null;\n  }\n\n  if (\n    file.size >\n    8 * 1024 * 1024\n  ) {\n    setImageLibraryError(\n      \"Images cannot exceed 8 MB.\",\n    );\n    return null;\n  }\n\n  const allowed =\n    new Set([\n      \"image/png\",\n      \"image/jpeg\",\n      \"image/webp\",\n      \"image/gif\",\n    ]);\n\n  if (!allowed.has(file.type)) {\n    setImageLibraryError(\n      \"Images must be PNG, JPEG, WEBP or GIF.\",\n    );\n    return null;\n  }\n\n  setImageUploadBusy(true);\n  setImageLibraryError(null);\n\n  try {\n    const formData =\n      new FormData();\n\n    formData.set(\n      \"file\",\n      file,\n    );\n\n    const response =\n      await fetch(\n        \"/api/editor/rich-text-images\",\n        {\n          method: \"POST\",\n          body: formData,\n        },\n      );\n\n    const data =\n      await response.json() as {\n        error?: string;\n        image?: RichTextLibraryImage;\n      };\n\n    if (\n      !response.ok ||\n      !data.image\n    ) {\n      throw new Error(\n        data.error ??\n          \"Unable to upload image.\",\n      );\n    }\n\n    setImageLibraryImages(\n      (current) => [\n        data.image!,\n        ...current.filter(\n          (entry) =>\n            entry.id !==\n            data.image!.id,\n        ),\n      ],\n    );\n\n    insertLibraryImage(\n      data.image.public_url,\n      range,\n    );\n\n    return data.image;\n  } catch (error) {\n    setImageLibraryError(\n      error instanceof Error\n        ? error.message\n        : \"Unable to upload image.\",\n    );\n\n    return null;\n  } finally {\n    setImageUploadBusy(false);\n  }\n}\n\nasync function loadImageLibrary(\n  search = imageLibrarySearch,\n) {\n  if (!canUseImageLibrary) {\n    return;\n  }\n\n  setImageLibraryLoading(true);\n  setImageLibraryError(null);\n\n  try {\n    const query =\n      new URLSearchParams();\n\n    query.set(\n      \"limit\",\n      \"200\",\n    );\n\n    if (search.trim()) {\n      query.set(\n        \"q\",\n        search.trim(),\n      );\n    }\n\n    const response =\n      await fetch(\n        `/api/editor/rich-text-images?${query.toString()}`,\n        {\n          cache: \"no-store\",\n        },\n      );\n\n    const data =\n      await response.json() as {\n        error?: string;\n        images?: RichTextLibraryImage[];\n      };\n\n    if (!response.ok) {\n      throw new Error(\n        data.error ??\n          \"Unable to load image library.\",\n      );\n    }\n\n    setImageLibraryImages(\n      data.images ?? [],\n    );\n  } catch (error) {\n    setImageLibraryError(\n      error instanceof Error\n        ? error.message\n        : \"Unable to load image library.\",\n    );\n  } finally {\n    setImageLibraryLoading(false);\n  }\n}\n\nfunction openImageLibrary() {\n  rememberImageInsertRange();\n  setImageLibraryOpen(true);\n  void loadImageLibrary(\"\");\n}\n\nfunction handleRichTextPaste(\n  event: React.ClipboardEvent<HTMLDivElement>,\n) {\n  if (\n    disabled ||\n    sourceMode ||\n    !canUseImageLibrary\n  ) {\n    return;\n  }\n\n  const htmlClipboard =\n    event.clipboardData.getData(\n      \"text/html\",\n    );\n\n  /*\n   * If a website supplied normal HTML containing an http(s) image,\n   * leave the browser's existing web-image paste behaviour untouched.\n   * We only upload actual clipboard image blobs such as Snipping Tool.\n   */\n  if (\n    /<img\\b[^>]*\\bsrc\\s*=\\s*[\"']https?:\\/\\//i.test(\n      htmlClipboard,\n    )\n  ) {\n    return;\n  }\n\n  const imageItem =\n    Array.from(\n      event.clipboardData.items,\n    ).find(\n      (item) =>\n        item.kind === \"file\" &&\n        item.type.startsWith(\n          \"image/\",\n        ),\n    );\n\n  const imageFile =\n    imageItem?.getAsFile();\n\n  if (!imageFile) {\n    return;\n  }\n\n  event.preventDefault();\n\n  const selection =\n    window.getSelection();\n\n  const editor =\n    editorRef.current;\n\n  const range =\n    editor &&\n    selection &&\n    selection.rangeCount > 0 &&\n    editor.contains(\n      selection\n        .getRangeAt(0)\n        .commonAncestorContainer,\n    )\n      ? selection\n          .getRangeAt(0)\n          .cloneRange()\n      : null;\n\n  void uploadRichTextImage(\n    imageFile,\n    range,\n  );\n}\n\n  const textLength = visibleLength(html);\n", "staff image library logic")
apply("components/editor/rich-text-editor.tsx", "          <ToolbarButton\n            label=\"Image\"\n            title=\"Insert image from URL\"\n            onClick={insertImage}\n            disabled={disabled || sourceMode}\n            wide\n          />\n", "          <ToolbarButton\n            label=\"Image\"\n            title=\"Insert image from URL\"\n            onClick={insertImage}\n            disabled={disabled || sourceMode}\n            wide\n          />\n          {canUseImageLibrary ? (\n            <ToolbarButton\n              label=\"Library\"\n              title=\"Open uploaded image library\"\n              onClick={openImageLibrary}\n              disabled={disabled || sourceMode}\n              wide\n            />\n          ) : null}\n", "mobile image library button")
apply("components/editor/rich-text-editor.tsx", "        <ToolbarButton\n          label=\"Image\"\n          title=\"Insert image from URL\"\n          onClick={insertImage}\n          disabled={disabled || sourceMode}\n          wide\n        />\n", "        <ToolbarButton\n          label=\"Image\"\n          title=\"Insert image from URL\"\n          onClick={insertImage}\n          disabled={disabled || sourceMode}\n          wide\n        />\n        {canUseImageLibrary ? (\n          <ToolbarButton\n            label=\"Library\"\n            title=\"Open uploaded image library\"\n            onClick={openImageLibrary}\n            disabled={disabled || sourceMode}\n            wide\n          />\n        ) : null}\n", "desktop image library button")
apply("components/editor/rich-text-editor.tsx", "      autoCapitalize=\"sentences\"\n      onInput={syncFromEditor}\n", "      autoCapitalize=\"sentences\"\n      onPaste={handleRichTextPaste}\n      onInput={syncFromEditor}\n", "Snipping Tool paste handler")
apply("components/editor/rich-text-editor.tsx", "\n{name ? (\n  <input className=\"components_editor_rich_text_editor_input_field\"\n", "\n      {imageLibraryOpen ? (\n        <div\n          className=\"fixed inset-0 z-[10020] flex items-center justify-center bg-black/70 p-4\"\n          data-sep-interaction-ignore=\"true\"\n          data-sep-ui-ignore=\"true\"\n        >\n          <div className=\"flex max-h-[85vh] w-full max-w-5xl flex-col border border-[rgb(var(--sep-colour-765937))]/70 bg-[rgb(var(--sep-colour-100c09))] shadow-[0_24px_70px_rgba(var(--sep-rgb-0-0-0),0.8)]\">\n            <div className=\"flex items-center justify-between gap-4 border-b border-[rgb(var(--sep-colour-60482e))]/45 px-4 py-3\">\n              <div>\n                <p className=\"font-serif text-lg text-[rgb(var(--sep-colour-dfc79c))]\">\n                  Image Library\n                </p>\n                <p className=\"mt-1 text-[8px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-806c52))]\">\n                  Uploaded rich-text images \u00b7 exact duplicates are reused automatically\n                </p>\n              </div>\n\n              <button\n                type=\"button\"\n                onClick={() => {\n                  setImageLibraryOpen(false);\n                  setImageLibraryError(null);\n                }}\n                className=\"border border-[rgb(var(--sep-colour-60482e))]/55 px-3 py-2 text-[10px] text-[rgb(var(--sep-colour-cbb28a))]\"\n              >\n                Close\n              </button>\n            </div>\n\n            <div className=\"flex flex-wrap items-center gap-2 border-b border-[rgb(var(--sep-colour-60482e))]/35 p-3\">\n              <input\n                type=\"search\"\n                value={imageLibrarySearch}\n                onChange={(event) =>\n                  setImageLibrarySearch(\n                    event.target.value,\n                  )\n                }\n                onKeyDown={(event) => {\n                  if (\n                    event.key === \"Enter\"\n                  ) {\n                    event.preventDefault();\n                    void loadImageLibrary(\n                      imageLibrarySearch,\n                    );\n                  }\n                }}\n                placeholder=\"Search file names...\"\n                className=\"min-w-[220px] flex-1 border border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-0d0907))] px-3 py-2 text-xs text-[rgb(var(--sep-colour-d7c4a5))] outline-none\"\n              />\n\n              <button\n                type=\"button\"\n                onClick={() =>\n                  void loadImageLibrary(\n                    imageLibrarySearch,\n                  )\n                }\n                disabled={imageLibraryLoading}\n                className=\"border border-[rgb(var(--sep-colour-765937))] bg-[rgb(var(--sep-colour-21190f))] px-3 py-2 text-[8px] uppercase tracking-[0.12em] text-[rgb(var(--sep-colour-d6bb8d))] disabled:opacity-50\"\n              >\n                Search\n              </button>\n\n              <label className=\"cursor-pointer border border-[rgb(var(--sep-colour-a17a49))]/70 bg-[rgb(var(--sep-colour-2a1c10))] px-3 py-2 text-[8px] uppercase tracking-[0.12em] text-[rgb(var(--sep-colour-efd09b))]\">\n                {imageUploadBusy\n                  ? \"Uploading...\"\n                  : \"Upload + Insert\"}\n\n                <input\n                  type=\"file\"\n                  accept=\"image/png,image/jpeg,image/webp,image/gif\"\n                  disabled={imageUploadBusy}\n                  className=\"sr-only\"\n                  onChange={(event) => {\n                    const file =\n                      event.currentTarget.files?.[0] ??\n                      null;\n\n                    event.currentTarget.value =\n                      \"\";\n\n                    if (file) {\n                      void uploadRichTextImage(\n                        file,\n                        imageInsertRangeRef.current,\n                      );\n                    }\n                  }}\n                />\n              </label>\n            </div>\n\n            {imageLibraryError ? (\n              <p className=\"border-b border-[rgb(var(--sep-colour-754137))]/45 bg-[rgb(var(--sep-colour-2b1714))] px-4 py-2 text-xs text-[rgb(var(--sep-colour-d58d82))]\">\n                {imageLibraryError}\n              </p>\n            ) : null}\n\n            <div className=\"min-h-0 flex-1 overflow-y-auto p-4\">\n              {imageLibraryLoading ? (\n                <p className=\"py-8 text-center text-xs text-[rgb(var(--sep-colour-806c52))]\">\n                  Loading images...\n                </p>\n              ) : imageLibraryImages.length ? (\n                <div className=\"grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5\">\n                  {imageLibraryImages.map(\n                    (image) => (\n                      <button\n                        key={image.id}\n                        type=\"button\"\n                        title={image.original_name}\n                        onClick={() => {\n                          insertLibraryImage(\n                            image.public_url,\n                            imageInsertRangeRef.current,\n                          );\n                          setImageLibraryOpen(false);\n                        }}\n                        className=\"group overflow-hidden border border-[rgb(var(--sep-colour-60482e))]/50 bg-[rgb(var(--sep-colour-0d0907))] text-left transition hover:border-[rgb(var(--sep-colour-a17a49))]\"\n                      >\n                        {/* eslint-disable-next-line @next/next/no-img-element */}\n                        <img\n                          src={image.public_url}\n                          alt={image.original_name}\n                          className=\"aspect-square w-full object-contain bg-black/20\"\n                        />\n\n                        <span className=\"block truncate border-t border-[rgb(var(--sep-colour-60482e))]/35 px-2 py-1.5 text-[8px] text-[rgb(var(--sep-colour-a99473))]\">\n                          {image.original_name}\n                        </span>\n                      </button>\n                    ),\n                  )}\n                </div>\n              ) : (\n                <p className=\"py-8 text-center text-xs text-[rgb(var(--sep-colour-806c52))]\">\n                  No uploaded rich-text images found.\n                </p>\n              )}\n            </div>\n          </div>\n        </div>\n      ) : null}\n\n{name ? (\n  <input className=\"components_editor_rich_text_editor_input_field\"\n", "image library modal")
